import{_ as o,o as a,c as i,a2 as t}from"./chunks/framework.BN2sqjC1.js";const m=JSON.parse('{"title":"Keycloak","description":"","frontmatter":{},"headers":[],"relativePath":"admin-guide/keycloak.md","filePath":"admin-guide/keycloak.md"}'),r={name:"admin-guide/keycloak.md"};function l(c,e,n,d,s,p){return a(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="keycloak" tabindex="-1">Keycloak <a class="header-anchor" href="#keycloak" aria-label="Permalink to &quot;Keycloak&quot;">​</a></h1><p>Il servizio è solo <strong>resource server</strong>: non gestisce password né sessioni. Keycloak autentica gli utenti (OIDC, Authorization Code + PKCE) e il servizio valida i JWT (chiavi JWKS, <code>iss</code>, <code>aud</code>, <code>azp</code>). In più controlla lo stato dell&#39;utente nel proprio database (sospensione, cache <code>OIDC_STATUS_CACHE_TTL</code>).</p><p><code>deploy/keycloak/realm-clarae.json</code> è il realm di riferimento (usato anche dallo stack di sviluppo): <strong>importarlo e poi rivedere</strong> i valori sensibili (segreti, redirect URI, utenti di prova) prima di un ambiente reale. <code>deploy/keycloak-prod/realm-clarae.json</code> è la sua variante di produzione, senza utenti di prova e con segreto e origine della Web UI presi dall&#39;ambiente.</p><h2 id="realm-clarae" tabindex="-1">Realm <code>clarae</code> <a class="header-anchor" href="#realm-clarae" aria-label="Permalink to &quot;Realm `clarae`&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Impostazione</th><th>Valore nel realm di riferimento</th><th>Note</th></tr></thead><tbody><tr><td><code>sslRequired</code></td><td><code>external</code></td><td>In produzione usare solo HTTPS.</td></tr><tr><td><code>registrationAllowed</code></td><td><code>false</code></td><td>Gli utenti si creano dalla console admin (o in Keycloak).</td></tr><tr><td><code>bruteForceProtected</code></td><td><code>true</code></td><td>Blocca i tentativi ripetuti; sbloccare da Keycloak se serve.</td></tr><tr><td><code>accessTokenLifespan</code></td><td>300 s</td><td>Il desktop rinnova in silenzio con il refresh token (keychain).</td></tr><tr><td><code>ssoSessionIdleTimeout</code></td><td>8 h</td><td></td></tr></tbody></table><h2 id="client" tabindex="-1">Client <a class="header-anchor" href="#client" aria-label="Permalink to &quot;Client&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Client</th><th>Tipo</th><th>Uso</th></tr></thead><tbody><tr><td><code>clarae-desktop</code></td><td>pubblico, PKCE S256, scope <code>offline_access</code></td><td>App desktop. Redirect: <code>http://127.0.0.1/*</code> (loopback), <code>clarae://auth/callback</code> (fallback, D-08).</td></tr><tr><td><code>clarae-web</code></td><td>pubblico, PKCE</td><td>Web UI. Redirect URI, post-logout redirect URI e Web origins sull&#39;origine pubblica <code>WEB_UI_ORIGIN</code> (vedi sotto).</td></tr><tr><td><code>clarae-api</code></td><td>solo audience</td><td>Il claim <code>aud</code> dei token deve contenere <code>clarae-api</code> (client scope <code>clarae-api-audience</code>, già assegnato ai due client).</td></tr><tr><td><code>clarae-admin-svc</code></td><td>confidential, <strong>service account</strong></td><td>Usato dal servizio per le operazioni admin sugli utenti (Admin REST API).</td></tr></tbody></table><h3 id="client-clarae-web-redirect-e-logout" tabindex="-1">Client <code>clarae-web</code>: redirect e logout <a class="header-anchor" href="#client-clarae-web-redirect-e-logout" aria-label="Permalink to &quot;Client `clarae-web`: redirect e logout&quot;">​</a></h3><p>Il realm di produzione <code>deploy/keycloak-prod/realm-clarae.json</code> (importato dallo stack Compose) prende l&#39;origine da <code>WEB_UI_ORIGIN</code>, sostituita da Keycloak all&#39;import. Con Helm il Keycloak è esterno e il client si configura a mano (scheda <em>Settings</em> → <em>Access settings</em>), con l&#39;origine pubblica della Web UI, per esempio <code>https://clarae.example.com</code>:</p><table tabindex="0"><thead><tr><th>Campo</th><th>Valore</th></tr></thead><tbody><tr><td>Valid redirect URIs</td><td><code>https://clarae.example.com/*</code> (il login torna su <code>/auth/callback</code>)</td></tr><tr><td>Valid post logout redirect URIs</td><td><code>https://clarae.example.com/*</code> (oppure <code>+</code>, che riusa i redirect URI)</td></tr><tr><td>Web origins</td><td><code>https://clarae.example.com</code> (uguale a <code>WEB_UI_ORIGIN</code>)</td></tr></tbody></table><p>Il post-logout redirect URI è obbligatorio: all&#39;uscita la Web UI chiede a Keycloak di tornare su <code>https://&lt;host&gt;/signed-out</code>, una pagina pubblica che dice «Sei uscito da Clarae notanda» e non rifà il login da sola. Se l&#39;indirizzo non è ammesso Keycloak mostra «Invalid redirect uri» <strong>senza chiudere la sessione SSO</strong>: la Web UI sembra disconnessa, ma chi preme di nuovo <em>Accedi</em> dallo stesso browser potrebbe entrare senza password con l&#39;utente precedente (fino a <code>ssoSessionIdleTimeout</code>). Non lasciare origini di sviluppo (<code>localhost</code>, <code>127.0.0.1</code>) nel client della Web UI; il test <code>services/cloud/internal/keycloak/realm_test.go</code> verifica sul realm di produzione che <code>${WEB_UI_ORIGIN}/signed-out</code> (oltre a <code>${WEB_UI_ORIGIN}/</code>) sia ammesso.</p><p><strong>Uscita e password.</strong> La Web UI chiude la sessione su Keycloak (revoca i token e passa <code>id_token_hint</code> e <code>client_id</code>), e il primo accesso dopo un&#39;uscita esplicita chiede sempre le credenziali (<code>prompt=login</code>), anche se Keycloak ricorda ancora l&#39;utente. Lo stesso vale per il client desktop, che esce senza aprire il browser: invia al <code>end_session_endpoint</code> il token di rinnovo, poi lo revoca dal <code>revocation_endpoint</code> della discovery. Se dopo «Esci» si rientra comunque senza password, controllare il client come sotto.</p><h3 id="controllare-un-realm-gia-importato" tabindex="-1">Controllare un realm già importato <a class="header-anchor" href="#controllare-un-realm-gia-importato" aria-label="Permalink to &quot;Controllare un realm già importato&quot;">​</a></h3><p>Keycloak parte con <code>--import-realm</code>, che <strong>salta un realm già esistente</strong>: le modifiche al file <code>realm-clarae.json</code> (anche quelle che arrivano con un aggiornamento) <strong>non hanno effetto</strong> su un realm creato prima. Per questo, dopo un aggiornamento e quando «Esci» non si comporta come descritto, controllare dalla console di Keycloak (realm <code>clarae</code>, <em>Clients</em> → <code>clarae-web</code> → <em>Settings</em> → <em>Access settings</em>) che:</p><ul><li><em>Valid post logout redirect URIs</em> ammetta <code>https://&lt;origine pubblica&gt;/signed-out</code> (va bene <code>https://&lt;origine pubblica&gt;/*</code>, oppure <code>+</code>);</li><li><em>Valid redirect URIs</em> ammetta <code>https://&lt;origine pubblica&gt;/*</code> e <em>Web origins</em> l&#39;origine;</li><li>non ci siano un <em>identity provider</em> o un broker che mantenga una sessione propria (in quel caso l&#39;uscita dalla Web UI non chiude la sessione di quel provider: l&#39;utente rientra con le credenziali ma non necessariamente con quelle di Clarae notanda).</li></ul><p>Lo stesso controllo sul client <code>clarae-desktop</code>: <em>Valid post logout redirect URIs</em> può contenere <code>clarae://auth/logout</code> e <code>http://127.0.0.1/*</code>; il logout del desktop non ne ha bisogno, ma resta registrato.</p><p>I nomi dei client e dell&#39;audience sono configurabili (<code>OIDC_DESKTOP_CLIENT_ID</code>, <code>OIDC_WEB_CLIENT_ID</code>, <code>OIDC_AUDIENCE</code>, <code>OIDC_ALLOWED_AZP</code>, <code>KC_ADMIN_CLIENT_ID</code>).</p><h2 id="service-account-clarae-admin-svc-ruoli-minimi" tabindex="-1">Service account <code>clarae-admin-svc</code>: ruoli minimi <a class="header-anchor" href="#service-account-clarae-admin-svc-ruoli-minimi" aria-label="Permalink to &quot;Service account `clarae-admin-svc`: ruoli minimi&quot;">​</a></h2><p>Al service account vanno assegnati <strong>solo</strong> questi ruoli del client <code>realm-management</code> (ADR-0012):</p><ul><li><code>manage-users</code>: creare utenti, reimpostare password, abilitare/disabilitare;</li><li><code>view-users</code>: leggere i dati degli utenti;</li><li><code>query-users</code>: cercare e filtrare.</li></ul><p><strong>Non</strong> assegnare <code>view-realm</code>, <code>manage-realm</code> né altri ruoli: la console non ne ha bisogno, e un segreto compromesso resterebbe limitato alla gestione utenti. Il segreto (<code>KC_ADMIN_CLIENT_SECRET</code>) va in un Secret; ruotarlo dalla scheda <em>Credentials</em> del client e aggiornare il Secret.</p><h2 id="ruoli-di-realm" tabindex="-1">Ruoli di realm <a class="header-anchor" href="#ruoli-di-realm" aria-label="Permalink to &quot;Ruoli di realm&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Ruolo</th><th>Effetto</th></tr></thead><tbody><tr><td><code>clarae-user</code></td><td>Utente standard.</td></tr><tr><td><code>clarae-admin</code></td><td>Accesso alla console di amministrazione (Web UI) e agli endpoint <code>/admin/*</code>. Assegnabile dalla console (azione <code>user.role</code>) o in Keycloak.</td></tr></tbody></table><p>Il servizio impedisce di rimuovere, sospendere o eliminare l&#39;<strong>ultimo amministratore</strong> (errore <code>INVALID_STATE</code>); il controllo prende un lock sulle righe degli amministratori attivi, quindi due amministratori che si rimuovono a vicenda nello stesso istante non possono lasciare il servizio senza amministratori.</p><p><strong>Cambio di ruolo e token già emessi (ADR-0041).</strong> Il ruolo vive in Keycloak ed è rispecchiato nel database a ogni accesso. Quando lo si cambia dalla console, il servizio lo aggiorna in Keycloak e nel database e da quel momento il database prevale sui token emessi <strong>prima</strong> del cambio: una revoca del ruolo <code>clarae-admin</code> vale dalla richiesta successiva (al più <code>OIDC_STATUS_CACHE_TTL</code> sulle altre repliche) anche se il token dell&#39;utente porta ancora il ruolo, e una promozione vale senza attendere un nuovo token. I token emessi dopo il cambio tornano a rispecchiare Keycloak, quindi un ruolo assegnato o tolto in seguito direttamente in Keycloak prevale al primo rinnovo del token. Per questo il cambio di ruolo dalla console richiede l&#39;Admin API di Keycloak (<code>KC_ADMIN_*</code>): senza, la console risponde <code>INVALID_STATE</code> invece di applicare un ruolo che il token successivo annullerebbe.</p><p><strong>Conflitto di identità.</strong> Il collegamento tra account Keycloak e account Clarae notanda avviene per <code>sub</code>, mai per e-mail. Se un account Keycloak viene eliminato e ricreato con la stessa e-mail (nuovo <code>sub</code>) mentre l&#39;account Clarae notanda precedente è ancora attivo o sospeso, il nuovo accesso non può creare una seconda riga con la stessa e-mail: ogni richiesta risponde <code>409 INVALID_STATE</code> con un messaggio esplicito (non più <code>500</code>), senza scrivere nulla. Il servizio non ricollega automaticamente l&#39;account per e-mail, perché chi controlla un indirizzo e-mail nel provider di identità otterrebbe i vault di un altro account. Rimedio nel <a href="./runbook.html#un-utente-riceve-409-invalid_state-a-ogni-richiesta">runbook</a>.</p><h2 id="gruppi" tabindex="-1">Gruppi <a class="header-anchor" href="#gruppi" aria-label="Permalink to &quot;Gruppi&quot;">​</a></h2><p>I gruppi di Clarae notanda (condivisione, config profile) vivono nel database del servizio e <strong>non</strong> sono i gruppi di Keycloak: nessun claim di gruppo nel token, nessuna importazione da LDAP/Keycloak (D-05). Se usate LDAP/AD come fonte utenti federata in Keycloak, gli utenti compaiono in Clarae notanda al primo accesso; l&#39;appartenenza ai gruppi Clarae notanda si gestisce dalla console.</p><h2 id="console-di-amministrazione-non-pubblica" tabindex="-1">Console di amministrazione non pubblica <a class="header-anchor" href="#console-di-amministrazione-non-pubblica" aria-label="Permalink to &quot;Console di amministrazione non pubblica&quot;">​</a></h2><p>La console di Keycloak e la sua API REST (<code>/admin/...</code>) e il realm <code>master</code> (dove accede l&#39;amministratore del server) non servono ai client: desktop e Web UI usano solo <code>/realms/clarae/...</code> (endpoint OIDC, pagine di login e account) e gli asset dei temi (<code>/resources/...</code>); il servizio cloud chiama l&#39;API admin direttamente su Keycloak, non tramite il proxy pubblico.</p><ul><li><strong>Compose on-premise:</strong> il proxy Caddy risponde <code>403</code> su <code>/admin</code> e <code>/realms/master</code> (anche con varianti di maiuscole, slash doppi, codifica <code>%xx</code> o parametri <code>;</code>) a meno che l&#39;indirizzo del client sia in <code>KEYCLOAK_ADMIN_FROM</code> (CIDR separati da spazio; il default <code>127.0.0.1/32</code> non corrisponde a nessun client esterno). Per amministrare: impostare in <code>.env</code> la rete degli amministratori (VPN, ufficio), <code>docker compose up -d proxy</code>, lavorare, poi togliere la variabile e ripetere il comando. Caddy deve vedere l&#39;IP reale del client: con un altro proxy o NAT davanti, verificare <code>remote_ip</code> nei log (<code>docker compose logs proxy</code>); le connessioni dall&#39;host stesso (per esempio un tunnel SSH verso la porta 443) arrivano dall&#39;indirizzo del bridge Docker, che non va aperto per intero.</li><li><strong>Kubernetes:</strong> Keycloak è esterno al chart. Applicare la stessa regola sull&#39;ingress o sul proxy di Keycloak (pubblicare solo <code>/realms/clarae</code> e <code>/resources</code>, oppure esporre la console su un host o una porta interna, opzione <code>hostname-admin</code> di Keycloak).</li></ul><p>Il primo avvio richiede comunque la console (ruolo <code>clarae-admin</code> al primo amministratore, utenti, rotazione del segreto di <code>clarae-admin-svc</code>): aprirla con <code>KEYCLOAK_ADMIN_FROM</code> per il tempo necessario.</p><h2 id="verifica-rapida" tabindex="-1">Verifica rapida <a class="header-anchor" href="#verifica-rapida" aria-label="Permalink to &quot;Verifica rapida&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://auth.example.com/realms/clarae/.well-known/openid-configuration</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> head</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://clarae.example.com/api/v1/client-config</span></span></code></pre></div><p>Dopo il primo accesso un token deve contenere <code>aud: clarae-api</code> e <code>azp: clarae-web</code> (o <code>clarae-desktop</code>); in caso contrario vedere <a href="./runbook.html#il-login-non-funziona">Il login non funziona</a>.</p>',35)])])}const h=o(r,[["render",l]]);export{m as __pageData,h as default};
